inout [31:0] IO_ddr_dq;
inout [3:0] IO_ddr_dqs;
inout [3:0] IO_ddr_dqs_n;
wire VCC;
wire GND;
  \~GW_DDR3_PHY_MC.Record_DDR3_Core  gw3_top (
    .memory_clk(memory_clk),
